diff --git a/lib/group_cpus.c b/lib/group_cpus.c
index e6e18d7a49bb..3c2229feb9c3 100644
--- a/lib/group_cpus.c
+++ b/lib/group_cpus.c
@@ -6,6 +6,7 @@
 #include <linux/kernel.h>
 #include <linux/slab.h>
