+    (50, NavarroColdOp::Poll),
+    (69, NavarroColdOp::Poll),
+    (87, NavarroColdOp::Poll),
+    (105, NavarroColdOp::Poll),
+    (123, NavarroColdOp::Poll),
+    (143, NavarroColdOp::Poll),
