+        // aux=0x09 (cp::aux_for_id(0x15, ..)), body = 32 + 16 (tag) = 48 bytes.
+        let frame = cp::seal_interactive(&[0x5au8; 16], &[0x11u8; 8], 0x15, 0, &req)?;
+        assert_eq!(frame.len(), 16 + 32 + 16);
+        assert_eq!(u16::from_le_bytes([frame[10], frame[11]]), 0x09);
