+static int snd_cht_mc_probe(struct platform_device *pdev)
+{
+	struct cht_mc_private *drv;
+	struct snd_soc_acpi_mach *mach = pdev->dev.platform_data;
+	struct snd_soc_aux_dev *aux_dev;
+	struct snd_soc_dai_link_component *codecs;
+	struct snd_soc_dai_link *dai_links;
+	struct snd_soc_card *card;
+	const void *codec_template;
+	size_t codecs_size;
+	const char *platform_name;
+	struct acpi_device *adev;
+	struct device *codec_dev;
+	bool has_acpi_codec = false;
+	bool sof_parent;
+	int ret;
+	int i;
+
+	drv = devm_kzalloc(&pdev->dev, sizeof(*drv), GFP_KERNEL);
+	if (!drv)
+		return -ENOMEM;
+
+	card = devm_kmemdup(&pdev->dev, &snd_soc_card_cht, sizeof(*card), GFP_KERNEL);
+	if (!card)
+		return -ENOMEM;
+
+	dai_links = devm_kmemdup(&pdev->dev, cht_dailink, sizeof(cht_dailink), GFP_KERNEL);
+	if (!dai_links)
+		return -ENOMEM;
+
+	aux_dev = devm_kmemdup(&pdev->dev, &cht_yb_headset_dev,
+			       sizeof(cht_yb_headset_dev), GFP_KERNEL);
+	if (!aux_dev)
+		return -ENOMEM;
+
+	card->dai_link = dai_links;
+	card->aux_dev = aux_dev;
+	drv->jack_nb.notifier_call = cht_yb_jack_event;
+
+	strscpy(drv->codec_name, RT5677_I2C, sizeof(drv->codec_name));
+
+	/* fixup codec name based on HID if ACPI node is present */
+	adev = acpi_dev_get_first_match_dev(mach->id, NULL, -1);
+	if (adev) {
+		has_acpi_codec = true;
+		snprintf(drv->codec_name, sizeof(drv->codec_name),
+			 "i2c-%s", acpi_dev_name(adev));
+		dev_info(&pdev->dev, "real codec name: %s\n", drv->codec_name);
+
+		put_device(&adev->dev);
+		for (i = 0; i < card->num_links; i++) {
+			if (dai_links[i].codecs->name &&
+			    !strcmp(dai_links[i].codecs->name,
+				    RT5677_I2C)) {
+				codecs_size = sizeof(*codecs) * dai_links[i].num_codecs;
+				codec_template = dai_links[i].codecs;
+				codecs = devm_kmemdup(&pdev->dev, codec_template, codecs_size,
+						      GFP_KERNEL);
+				if (!codecs)
+					return -ENOMEM;
+
+				codecs->name = drv->codec_name;
+				dai_links[i].codecs = codecs;
+				break;
+			}
+		}
+	}
+
+	codec_dev = bus_find_device_by_name(&i2c_bus_type, NULL,
+					    drv->codec_name);
+	if (!codec_dev)
+		return -EPROBE_DEFER;
+
+	if (has_acpi_codec) {
+		ret = devm_acpi_dev_add_driver_gpios(codec_dev, cht_yb_gpios);
+		if (ret)
+			dev_warn(&pdev->dev, "Unable to add GPIO mapping table: %d\n",
+				 ret);
+	}
+	put_device(codec_dev);
+
+	/* Override platform name, if required. */
+	card->dev = &pdev->dev;
+	platform_name = mach->mach_params.platform;
+
+	ret = snd_soc_fixup_dai_links_platform_name(card, platform_name);
+	if (ret) {
+		dev_err(&pdev->dev, "snd_soc_fixup_dai_links_platform_name failed: %d\n",
+			ret);
+		return ret;
+	}
+
+	drv->mclk = devm_clk_get(&pdev->dev, "pmc_plt_clk_3");
+	if (IS_ERR(drv->mclk)) {
+		dev_err(&pdev->dev,
+			"Failed to get MCLK from pmc_plt_clk_3: %ld\n",
+			PTR_ERR(drv->mclk));
+		return PTR_ERR(drv->mclk);
+	}
+	snd_soc_card_set_drvdata(card, drv);
+
+	sof_parent = snd_soc_acpi_sof_parent(&pdev->dev);
+
+	/* set the card and driver name */
+	if (sof_parent) {
+		card->name = SOF_CARD_NAME;
+		card->driver_name = SOF_DRIVER_NAME;
+	} else {
+		card->name = CARD_NAME;
+		card->driver_name = DRIVER_NAME;
+	}
+
+	/* register the soc card */
+	ret = devm_snd_soc_register_card(&pdev->dev, card);
+	if (ret) {
+		dev_err(&pdev->dev,
+			"snd_soc_register_card failed %d\n", ret);
+		return ret;
+	}
+	platform_set_drvdata(pdev, card);
+
+	return 0;
+}
+
+static struct platform_driver snd_cht_mc_driver = {
+	.driver = {
+		.name = "cht-yogabook",
+	},
+	.probe = snd_cht_mc_probe,
+};
+
+module_platform_driver(snd_cht_mc_driver);
+
+MODULE_DESCRIPTION("Lenovo Yoga Book YB1-X91 machine driver");
+MODULE_LICENSE("GPL");
+MODULE_ALIAS("platform:cht-yogabook");
-- 
2.53.0

The Lenovo Yoga Book YB1-X91 rear camera contains a WV517S
voice-coil actuator. Add a V4L2 lens subdevice exposing the standard
10-bit FOCUS_ABSOLUTE control and the device ringing-control mode.

Tie register access to runtime PM so the IPU bridge sensor link keeps
shared power resources active. Propagate PM acquisition failures and
restore the drive mode and requested focus position after resume.

The register addresses and drive-mode value are derived from Intel's
GPL-2.0 WV517 driver. Retain its copyright notice.

Link: https://github.com/jekhor/yogabook-linux-android-kernel/blob/574bae692716f1b14093497bfab8a007fe8e460b/drivers/external_drivers/camera/drivers/media/i2c/wv517.c

