@@ -460,6 +477,8 @@ struct dt_info *build_dt_info(unsigned int dtsflags,
 	dti->dt = tree;
 	dti->boot_cpuid_phys = boot_cpuid_phys;
 
+	fill_fullpaths(dti->dt, "");
+
 	return dti;
 }
 
